// JIRA-4829: Increase cache TTL to 600s for /api/v1/data and /api/v2/data endpoints
pipeline {
  agent any
  stages {
    stage('Update Cache TTL') {
      steps {
        script {
          // Set TTL to 600 seconds for the data endpoints to mitigate DB load
          sh "sed -i 's/ttl: [0-9]*/ttl: 600/' jenkins/pipeline.groovy"
        }
      }
    }
  }
}

